What is the output of the following code?

#include <stdio.h>
int main() {
    int x = 1;
    int sum = 0;
    while (x <= 6) {
        if (x % 2 == 0) {
            x++;
            continue;
        }
        sum += x;
        printf("%d ", sum);
        x++;
    }
    printf("| %d", x);
    return 0;
}

