What is the output of the following code?

#include <stdio.h>
int main() {
    int x = 7;
    int y = 0;
    if (x % 2 == 0 || ++y > 0)
        if (x & 1 && y--)
            printf("Odd");
        else
            printf("Even");
    else
        printf("None");
    printf(" %d %d", x, y);
    return 0;
}

What is the output of the following code?

#include <stdio.h>
int main() {
    int sum = 0;
    int i;
    for (i = 1; i <= 10; i += 2) {
        if (i % 3 == 0)
            continue;
        if (sum > 10)
            break;
        sum += i * (i > 4 ? 2 : 1);
    }
    printf("%d %d", sum, i);
    return 0;
}

