What is the output of the following code?

#include <stdio.h>
int main() {
    int numbers[5] = {10, 20, 30, 40, 50};
    int *p = numbers + 1;
    int *q = &numbers[4];
    *p++ += 5;
    *++p *= 2;
    q -= 2;
    printf("%d %d %d ", numbers[1], numbers[3], *q);
    printf("%d %d", (int)(&numbers[4] - p), 2[numbers]);
    return 0;
}

What is the output of the following code?

#include <stdio.h>
int counter() {
    static int n = 0;
    return ++n;
}
void swap(int a, int b) {
    int t = a;
    a = b;
    b = t;
}
int f(int n) {
    if (n <= 1)
        return counter();
    int x = f(n - 1);
    int y = f(n - 2);
    return x + y * 10;
}
int main() {
    int a = 3, b = 5;
    swap(a, b);
    printf("%d %d ", a, b);
    printf("%d ", f(4));
    printf("%d", counter());
    return 0;
}

